parameters.query:
UPDATE matches
SET notified = true, notified_at = now()
WHERE match_id = ANY(ARRAY[{{ $('Email_template').item.json.match_ids.join(',') }}]::bigint[]);

parameters.jsCode:
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r.match_id !== undefined);

if (rows.length === 0) {
  return [];   // nothing to send, the workflow stops here
}

// Group matches by user
const byUser = {};
for (const r of rows) {
  if (!byUser[r.user_id]) {
    byUser[r.user_id] = { user_id: r.user_id, name: r.name, matches: [] };
  }
  byUser[r.user_id].matches.push(r);
}

const testInboxes = [
  'jainshashwat528+one@gmail.com',
  'jainshashwat528+two@gmail.com',
  'jainshashwat528+three@gmail.com',
];

const out = [];
Object.values(byUser).forEach((u, idx) => {
  const lines = u.matches.map((m, i) =>
    `${i + 1}. ${m.product_name} (${m.source}): ${m.interest_rate}% interest`
  ).join('\n');

  const body =
`Hi ${u.name},

Based on your profile, you may qualify for these personal loans:

${lines}

These are indicative matches. Please check each lender's site for final terms.

Regards,
loan-match`;

  out.push({
    json: {
      user_id: u.user_id,
      to: testInboxes[idx % testInboxes.length],
      subject: `You may qualify for ${u.matches.length} personal loan offer(s)`,
      body,
      match_ids: u.matches.map(m => Number(m.match_id)),
    },
  });
});

return out;
